mapper.select:
SELECT id, transaction_date, type, category, amount, memo, is_recurring, recurring_origin_id, is_hidden
FROM daily_transaction
WHERE user_id = #{userId}
  AND YEAR(transaction_date) = #{year}
  AND MONTH(transaction_date) = #{month}
ORDER BY transaction_date, id

SELECT id, transaction_date, type, category, amount, memo, is_recurring, recurring_origin_id, is_hidden
FROM daily_transaction
WHERE id = #{id} AND user_id = #{userId}

SELECT COALESCE(SUM(amount), 0)
FROM daily_transaction
WHERE user_id = #{userId}
  AND YEAR(transaction_date) = #{year}
  AND MONTH(transaction_date) = #{month}
  AND type = #{type}

SELECT category, COALESCE(SUM(amount), 0) AS total
FROM daily_transaction
WHERE user_id = #{userId}
  AND YEAR(transaction_date) = #{year}
  AND MONTH(transaction_date) = #{month}
  AND type = #{type}
GROUP BY category

SELECT id, transaction_date, type, category, amount, memo, is_recurring, recurring_origin_id
FROM daily_transaction
WHERE user_id = #{userId}
  AND is_recurring = TRUE
  AND recurring_origin_id IS NULL
  AND transaction_date <= #{onOrBefore}

SELECT COUNT(*)
FROM daily_transaction
WHERE recurring_origin_id = #{originId}
  AND YEAR(transaction_date) = #{year}
  AND MONTH(transaction_date) = #{month}

SELECT id, transaction_date, type, category, amount, memo, is_recurring, recurring_origin_id, is_hidden
FROM daily_transaction
WHERE user_id = #{userId}
  AND YEAR(transaction_date) = #{year}
  AND MONTH(transaction_date) = #{month}
  AND is_hidden = FALSE

      AND transaction_date >= #{sinceDate}


      AND transaction_date <= #{untilDate}

ORDER BY transaction_date, id
